import Phaser from 'phaser'
var replayButton 
export default class GameOverScene extends
Phaser.Scene 
{ 
    constructor () 
    {  
        super('game-over-scene')
    }

    init (data) 
    {
        this.score = data.score 
    }
    
    preload() 
    {
        this.load.image('background', 'images/bg_layer1.png')
        this.load.image('gameover', 'images/gameover.png')
        this.load.image('replay', 'images/replay.png')
    }

    create() 
    { 
        this.add.image (200,320, 'background')
        this.add.image (200, 320, 'gameover')
        this.replayButton= this.add.image (200, 75, 'replay').setInteractive()
        this.replayButton.once('pointerup', () => { this.scene.start('corona-buster-scene') }, this)

        // @ts-ignore
        this.add.text(40, 500, 'SCORE:', {fontSize: '60px', fill: '#000'})
        // @ts-ignore
        this.add.text(280, 500, this.score, { fontSize: '60px', fill: '#000'})
    }

}
